/**
 * Seed a persistent coloring fixture on the E2E test account.
 *
 * Creates (idempotently, matched by stable title/name):
 *   - one coloring book "E2E Fixture Coloring Book" with total_pages pages
 *     (pages are auto-generated by a backend hook on book create)
 *   - one coloring medium "E2E Fixture Medium" owned by the same user
 *
 * Read-only coloring E2E specs reference these by id so they run against real
 * data instead of skipping on the empty account. The seed never mutates a book
 * the user might be using; it owns its own fixture records by title.
 *
 * Usage:
 *   set -a; . ./.env.e2e; set +a
 *   export VITE_POCKETBASE_URL=https://data.organizedglitter.app
 *   node scripts/seed-e2e-coloring-fixture.mjs
 *
 * Prints the resulting ids as KEY=VALUE lines (E2E_COLORING_BOOK_ID,
 * E2E_COLORING_PAGE_ID, E2E_COLORING_MEDIUM_ID) so they can be appended to
 * .env.e2e.local or stored as CI secrets. Re-running is safe and returns the
 * same ids.
 */

import PocketBase from 'pocketbase';

const FIXTURE_BOOK_TITLE = 'E2E Fixture Coloring Book';
const FIXTURE_MEDIUM_NAME = 'E2E Fixture Medium';
const FIXTURE_TOTAL_PAGES = 3;

const pocketBaseUrl = process.env.VITE_POCKETBASE_URL ?? 'http://localhost:8090';
const email = process.env.E2E_TEST_EMAIL;
const password = process.env.E2E_TEST_PASSWORD;

if (!email || !password) {
  console.error('Missing E2E_TEST_EMAIL or E2E_TEST_PASSWORD. Source .env.e2e first.');
  process.exit(1);
}

const pb = new PocketBase(pocketBaseUrl);
await pb.collection('users').authWithPassword(email, password);
const userId = pb.authStore.record?.id;
if (!userId) {
  console.error('PocketBase did not return an authenticated E2E user.');
  process.exit(1);
}

const findOrCreateBook = async () => {
  const existing = await pb.collection('coloring_books').getFullList({
    filter: pb.filter('user = {:u} && title = {:t}', { u: userId, t: FIXTURE_BOOK_TITLE }),
  });
  if (existing.length > 0) return existing[0];
  return pb.collection('coloring_books').create({
    user: userId,
    title: FIXTURE_BOOK_TITLE,
    status: 'in_progress',
    total_pages: FIXTURE_TOTAL_PAGES,
  });
};

const findOrCreateMedium = async () => {
  const existing = await pb.collection('coloring_mediums').getFullList({
    filter: pb.filter('user = {:u} && name = {:n}', { u: userId, n: FIXTURE_MEDIUM_NAME }),
  });
  if (existing.length > 0) return existing[0];
  return pb.collection('coloring_mediums').create({
    user: userId,
    name: FIXTURE_MEDIUM_NAME,
    type: 'colored_pencil',
    brand: 'E2E Brand',
    color_count: 24,
  });
};

const book = await findOrCreateBook();
const medium = await findOrCreateMedium();

const pages = await pb.collection('coloring_pages').getFullList({
  filter: pb.filter('book = {:b}', { b: book.id }),
  sort: 'page_number',
});
if (pages.length === 0) {
  console.error(
    `Book ${book.id} has no pages; the auto-generate hook may not have run. Check total_pages.`
  );
  process.exit(1);
}

console.log(`E2E_COLORING_BOOK_ID=${book.id}`);
console.log(`E2E_COLORING_PAGE_ID=${pages[0].id}`);
console.log(`E2E_COLORING_MEDIUM_ID=${medium.id}`);
console.error(
  `Seeded: book "${FIXTURE_BOOK_TITLE}" (${book.id}) with ${pages.length} pages, ` +
    `medium "${FIXTURE_MEDIUM_NAME}" (${medium.id}).`
);
